public interface IOrderPort { Task<Receipt> PlaceOrderAsync(Order o, CancellationToken ct); }

public sealed class LegacyOrderAdapter(IHttpClientFactory http) : IOrderPort
{
    public async Task<Receipt> PlaceOrderAsync(Order o, CancellationToken ct)
    {
        try
        {
            var dto = LegacyOrderDto.From(o);                 // translator
            var resp = await http.CreateClient("legacy").PostAsJsonAsync("/orders", dto, ct);
            resp.EnsureSuccessStatusCode();
            var body = await resp.Content.ReadFromJsonAsync<ReceiptDto>(ct);
            return (body ?? throw new OrderRejected("legacy returned empty body")).ToDomain();
        }
        catch (HttpRequestException ex)
        {
            throw new OrderUnavailable("legacy unavailable", ex);
        }
        catch (JsonException ex)
        {
            throw new OrderRejected("legacy returned invalid JSON", ex);
        }
    }
}
